UPDATE companies SET description='Steel City Metal Inc was founded in 1996 in Westover, Alabama, as a family-owned and operated business. The company operates from a facility on Old Highway 280 in Westover, with an administrative office in Birmingham, serving the Greater Birmingham area and surrounding states.

The shop provides welding, fabrication, powder coating, and sandblasting services. Its welders hold AWS certification, and the team brings over 30 years of combined experience in welding and powder coating. Steel City Metal functions as a full-service general contractor for metalwork, handling structural and decorative welding, custom fabrication for homes and businesses, and electrostatic powder coating cured under heat. The company does not sell raw materials but supplies the materials required for each project.

Customers span commercial, industrial, and residential sectors. Projects range from repairs and maintenance for factories and shops to custom builds such as the 15,000-pound "Inception" sculpture installed on the Birmingham walking trail, a collaboration with sister company SuperiorScape. The firm also serves homeowners seeking decorative metalwork and businesses needing code-compliant fabrication.

The company emphasizes integrity, safety, and communication as its differentiators. Leadership cites a team approach rooted in family ownership, with AWS-certified welders prioritizing safety on every job. Steel City Metal says it was built on delivering the cleanest welds and structurally sound structures while maintaining outstanding customer service and attention to detail.', certifications=ARRAY['AWS Certified']::text[], profile='{"capabilities": ["Welding (AWS certified, structural, decorative, repair)", "Fabrication (custom, repair, maintenance)", "Powder coating (electrostatic, heat-cured)", "Sandblasting"], "industries": ["Commercial", "Industrial", "Residential"], "materials": ["Sheet metal", "Alloys", "Railroad steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["AWS-certified welders with over 30 years of welding and powder coating experience", "Family-owned and operated with a team-based approach", "Safety-first culture on every project", "Full-service general contractor for welding, fabrication, and powder coating", "Materials supplied per project; no raw material sales"], "facts_used": ["Founded 1996 -> db", "Headquarters Westover, Alabama -> db", "Family-owned and operated -> /", "AWS certified welders -> /", "Over 30 years welding & powder coating experience -> /", "Services: welding, fabrication, powder coating, sandblasting -> /services", "Industries served: commercial, industrial, residential -> /services", "Team members: Mike Sampsell (President & CEO), Steven Clark (VP & Sales Manager), etc. -> /about-us", "Inception sculpture project (15,000 lbs, 26 ft tall) -> /", "Full-service general contractor for welding, fabrication, powder coating -> /about-us", "Safety-first priority -> /", "Do not sell raw materials, provide materials per project -> /", "Materials: sheet metal, alloys, railroad steel -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Steel City Metal, Inc. takes pride in its ability to fabricate exactly what you want, to take your residential and commercial areas to the next level", "founded_year": "1996", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='steel-city-metal-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Steel Masters NYC operates from a fabrication shop in Brooklyn, New York. The company was founded in 1972 and remains owner-operated and family-run, carrying more than five decades of continuous service across the New York City metropolitan area.

The shop produces custom steel and iron fabrications for both structural and architectural applications. All items are custom-measured in the field, fabricated in the Brooklyn shop, and installed by the company''s own crews.

The customer base spans general contractors, property managers, building owners, facilities managers, architects, engineers, co-op and condo boards, restaurant and retail operators, and homeowners of brownstones, townhouses, and rowhouses. Institutional and commercial clients include hospitals, schools, factories, apartment complexes, and government properties throughout the five boroughs, Long Island, and Westchester.

The company emphasizes that the same organization that welds the steel also installs it, allowing it to hold tolerances and stand behind the finished work. Every project begins with a free estimate based on supplied drawings or photos, followed by a site visit for field measurements, a written proposal, and optional shop drawings for a fee. This hands-on, in-house approach has been the operating model since 1972.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom steel fabrication", "Structural steel fabrication", "Welding", "Field measurement", "Installation", "Shop drawings (for fee)", "Modifications & repairs", "Custom iron works", "Galvanized grating fabrication", "Expanded metal fabrication", "Hydraulic door systems fabrication", "Waterproof door fabrication", "Cellar door fabrication", "Staircase fabrication", "Railing fabrication", "Fencing & gate fabrication", "Garbage bin enclosure fabrication", "Security cage & partition fabrication", "Window guard fabrication", "Roof access ladder fabrication", "Roof dunnage fabrication", "Catwalk & mezzanine fabrication", "Outdoor deck fabrication", "Coiling door & rolldown gate fabrication"], "industries": ["Commercial construction", "Industrial", "Institutional", "Residential multi-family", "Hospitality", "Healthcare", "Education", "Government", "Property management", "General contracting"], "materials": ["Steel", "Iron", "Galvanized steel", "Diamond plate", "Grating", "Expanded metal", "Welded steel mesh"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom-measured, shop-fabricated in Brooklyn, installed by own crew", "Field measurements taken by company personnel before fabrication", "Owner-operated and insured since 1972", "Single-source responsibility: fabrication and installation in-house", "Free estimates with pricing from initial conversation"], "facts_used": ["Founded 1972 -> db, /, /about-us", "Headquarters 135 Liberty Ave, Brooklyn, NY -> /, /about-us, /services", "Family-owned, owner-operated -> /about-us", "Insured since 1972 -> /, /about-us", "Fabrication in Brooklyn shop, installation by own crew -> /, /about-us, /services", "Serves five boroughs, Long Island, Westchester -> /, /about-us, /services", "Customer types: general contractors, property managers, building owners, facilities managers, architects, engineers, co-op/condo boards, restaurant/retail operators, homeowners -> /, /about-us", "Institutional clients: hospitals, schools, factories, apartment complexes, government properties -> /about-us", "Product lines: cellar doors, hydraulic Ez Lift doors, waterproof bulkhead doors, staircases, railings, fencing, garbage enclosures, expanded metal, security cages, window guards, roof ladders, roof dunnage, catwalks, mezzanines, structural alterations, coiling doors, outdoor decks -> /, /services", "Process: free estimate, field measurement, written proposal, optional shop drawings, fabrication, installation -> /, /services", "Materials: steel, iron, galvanized steel, diamond plate, grating, expanded metal, welded steel mesh -> /, /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Every product is fabricated in our Brooklyn shop and installed by our own crew - no shipping, no shortcuts.", "founded_year": "1972", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='steel-masters-nyc' AND approved AND profile IS NULL;
UPDATE companies SET description='Stelray Plastic Products Inc is a family-owned contract manufacturer based in Ansonia, Connecticut. The company has been operating for over 50 years, emphasizing American-made production and a full-service approach to precision injection molding and mold building.

The company operates a 42,000-square-foot facility that houses molding, in-house tool making, quality control, warehousing, secondary operations, and offices. Its molding capacity ranges from 22 to 620 tons, supporting conventional and rotary horizontal injection machines capable of insert molding, overmolding, and multi-material molding. Stelray offers rapid prototyping, design-for-manufacturing reviews, and a suite of post-mold secondary operations including ultrasonic welding, pad printing, heat-staking, soldering, assembly, and packaging. Production volumes span from 100 units to 100 million units annually.

Stelray serves a diverse set of industries: aerospace and automotive, consumer appliance, defense and security, electronics and instrumentation, medical and dental, and water and chemical filtration. The company is FDA registered for medical devices and compliant with current Good Manufacturing Practices (cGMP) and 21 CFR 820.

Stelray differentiates itself through its family-owned heritage, a full-service in-house tool room, advanced metrology lab with first-article inspection and validation capabilities, and a lean manufacturing philosophy. The company states that its expert engineering staff works with customers to design parts that are both manufacturable and cost-effective from prototype through production.', certifications=ARRAY['ISO 9001:2015','FDA 21 CFR 820','cGMP compliant','UL-Underwriters Laboratories','American National Standards Institute']::text[], profile='{"capabilities": ["Custom plastic injection molding", "Precision injection molding", "Mold making / tool making", "Rapid prototyping", "Design for Manufacturing (DFM) review", "Insert molding", "Overmolding", "Multi-material molding", "Large part injection molding", "White room molding", "Ultrasonic welding", "Pad printing", "Heat-staking", "Soldering", "Assembly", "Packaging", "First-article inspection (FAI)", "Validation & capability studies", "PPAP investigations", "Quality assurance", "Product validation services", "Process capability studies", "Mold maintenance tracking", "High-speed part measuring", "Complete lot traceability"], "industries": ["Aerospace", "Automotive", "Consumer Appliance", "Defense & Security", "Electronics & Instrumentation", "Medical & Dental", "Water & Chemical Filtration"], "materials": ["Commodity-grade polymers", "High-performance engineered resins", "Biodegradable materials"], "equipment": ["22\u2013620 ton injection molding machines", "Conventional and rotary horizontal injection molding machines", "Advanced metrology lab", "High-speed part measuring equipment", "AI-driven DFM software"], "volume": "100 units to 100 million units", "lead_time": "", "tolerances": "", "built_on": ["Family-owned, American-made, over 50 years experience", "Full-service in-house tool room", "22\u2013620 ton injection molding machines", "ISO 9001:2015 certified and FDA registered", "Advanced metrology lab with FAI and validation capabilities"], "facts_used": ["Family owned. American made. For over 50 years. -> /", "42,000 square foot facility -> /about", "22 to 620 ton molding machines -> /", "ISO 9001:2015 certified -> /", "FDA registered -> /", "cGMP compliant -> /", "Industries served: Aerospace & Automotive, Consumer Appliance, Defense & Security, Electronics & Instrumentation, Medical & Dental, Water & Chemical Filtration -> /", "Full-service, in-house tool room -> /", "Rapid prototyping -> /", "Design for Manufacturing (DFM) review -> /", "Secondary operations: ultrasonic welding, pad printing, heat-staking, soldering, assembly, packaging -> /", "Production volume of 100 units to 100 million units -> db (products)", "Advanced metrology lab -> /", "FAI, Validation & Capability studies -> /", "PPAP investigations -> /", "Complete lot traceability -> /", "High-speed part measuring -> /", "Mold maintenance tracking -> /", "Product validation services -> /", "UL-Underwriters Laboratories -> /", "American National Standards Institute -> /", "Conventional & Rotary injection horizontal molding machines -> db (capabilities)", "Insert molding, overmolding & multi-material molding -> db (capabilities)", "Large part injection molding -> db (capabilities)", "White room environment -> /", "Tool transfers -> /", "Value-add finishing -> /", "Engineered & performance resins -> /", "Biodegradable materials -> /", "AI-driven software for DFM -> /", "Lean Manufacturing philosophy -> /", "Expert engineering services -> /about", "Management staff with many years of hands-on experience -> /about", "Assist customer in designing parts cost-effectively -> /about"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "A Contract Manufacturer of Precision Injection Molds and Molded Products", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Famil