UPDATE companies SET description='Founded in 2003 in Linden, New Jersey, Stylus Apparel began as a factory-direct apparel manufacturer serving clothing lines and corporate clients. The company operates its production facility minutes outside New York City.

Stylus Apparel provides contract garment manufacturing services including screen printing (plastisol, water-based, discharge, foil, and specialty inks), embroidery (direct, 3D puff, tackle twill, appliqué, patches, and distress techniques), sublimation printing (blank garment and cut-and-sew), and full cut-and-sew manufacturing with tech pack design, pattern grading, sampling, and production. The company also produces woven fabric labels. All work is performed in-house at its state-of-the-art cut-and-sew facility, which the company says has capacity for large volumes.

The company serves clothing brands ranging from start-up lines to established private labels, as well as corporate customers needing custom merchandise and employee uniforms. Examples include young start-up brands, well-established private labels, and corporate clients ordering screen-printed T-shirts or embroidered polo shirts for managers.

Stylus Apparel emphasizes its factory-direct model, with all production kept under one roof from design to distribution. It highlights 100% American labor and a "Made in USA" commitment, along with more than 30 years of cut-and-sew experience among its team.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Plastisol Screen Printing", "Water Based & Discharge Screen Printing", "Foil Screen Printing", "Specialty Screen Printing Inks", "Direct Embroidery", "3D Puff Embroidery", "Tackle Twill & Applique", "Embroidered Patches", "Distress Services", "Blank Apparel Sublimation", "Cut and Sew Sublimation", "Tech Pack Design", "Pattern & Grading", "Sampling & Production", "Woven Fabric Labels", "Cut & Sew Manufacturing"], "industries": ["Clothing brands", "Private label", "Corporate apparel", "Start-up clothing lines", "Established brands"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Factory-direct production in own facility", "100% American labor (Made in USA)", "Design-to-distribution under one roof", "Over 30 years of cut-and-sew experience", "Contract and commercial screen printing and embroidery services"], "facts_used": ["Founded in 2003 in Linden, New Jersey -> /", "Factory-direct apparel manufacturer -> /", "Production facility minutes outside New York City -> /", "All work produced in own facility -> /", "Contract garment manufacturing services -> /", "Screen printing (plastisol, water-based, discharge, foil, specialty inks) -> /services", "Embroidery (direct, 3D puff, tackle twill, appliqu\u00e9, patches, distress) -> /services", "Sublimation printing (blank garment and cut-and-sew) -> /services", "Cut-and-sew manufacturing with tech pack design, pattern grading, sampling, production -> /services", "Woven fabric labels -> /services", "State-of-the-art cut-and-sew facility with large volume capacity -> /services", "Serves clothing brands, private labels, corporate customers -> /", "Examples: start-up brands, established private labels, corporate merchandise and uniforms -> /", "Factory-direct model, design to distribution under one roof -> /", "100% American labor, Made in USA -> /", "Over 30 years of cut-and-sew experience -> /services", "Headquarters: Linden, New Jersey -> db", "Company type: Contract manufacturer / job shop -> /", "Makes products: yes -> /", "Social media platforms: Instagram, Facebook, YouTube, X, TikTok, LinkedIn -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We are contract garment manufacturers with the ability to create a large number of garments on demand.", "founded_year": "2003", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='stylus-apparel' AND approved AND profile IS NULL;
UPDATE companies SET description='Subsalve USA is based in North Kingstown, Rhode Island, and was founded in 1977 by Richard Fryburg. The company began as a specialist in engineered inflatables for marine and military applications, and in 2017 it became part of Performance Inflatables Co LLC.

The company designs and manufactures a range of engineered inflatables, including underwater lift bags, inflation hose assemblies, station manifolds, inflation yoke assemblies, and acoustic and remote tablet actuation systems. It maintains an inventory of standard products and offers custom design services for specialized applications.

Subsalve serves industries such as aircraft recovery, ship and boat salvage, marine construction, offshore oilfield diving, explosive ordnance disposal, pipeline and tunnel construction, proofload testing, public safety, research, and shipyard operations. Its customers include the U.S. Department of Defense, all branches of the U.S. Armed Forces, NASA, the FBI, private-sector companies, and governments of more than 30 foreign countries.

The company differentiates itself by using polyurethane-coated fabrics—nylon, polyester, and Kevlar—in all its lift bags, which it says provides superior puncture, abrasion, and chemical resistance. All products are made in the USA, tested before shipping, and carry a one-year warranty. Subsalve holds compliance with IMCA D-016-AIRBAGS, ABS, and U.S. Department of Defense standards, and holds multiple patents for its designs.', certifications=ARRAY['IMCA D-016-AIRBAGS','ABS','U.S. Department of Defense Standards']::text[], profile='{"capabilities": ["Engineered inflatable design and manufacturing", "Underwater lift bag production", "Inflation hose assembly manufacturing", "Station manifold fabrication", "Inflation yoke assembly", "Acoustic actuation systems", "Remote tablet actuation systems", "Custom inflatable design", "Proofload testing services", "Major repair kit supply"], "industries": ["Aircraft recovery", "Ship salvage", "Yacht salvage", "Boat salvage", "Marine construction", "Offshore oilfield diving", "Explosive ordnance disposal", "Pipeline construction", "Tunnel construction", "Proofload testing", "Public safety", "Research", "Shipyard operations", "Draft reduction", "Military", "Commercial", "Scientific", "Recreational"], "materials": ["Polyurethane-coated fabrics", "Nylon", "Polyester", "Kevlar", "Urethane blends"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Only major lift bag brand offering polyurethane-coated fabrics in all products", "All products made in the USA and tested before shipping", "Inventory of standard products for prompt delivery", "Custom design services for specialized applications", "Compliance with IMCA D-016-AIRBAGS, ABS, and U.S. DoD standards"], "facts_used": ["Founded 1977 in North Kingstown, Rhode Island -> /about-us", "Founder Richard Fryburg inducted into ACDI Hall of Fame 2020 -> /about-us", "Became part of Performance Inflatables Co LLC in 2017 -> /about-us", "Designs and manufactures e