terials"], "equipment": [], "volume": "", "lead_time": "3, 5, and 10-day turns for assembly", "tolerances": "Fine pitch to 0.04 mils advanced; tight tolerance drilling", "built_on": ["One of the largest PCB manufacturers in North America", "Seven connected high-tech facilities across eight North American locations", "Field application engineers deployed across North America", "Redundant manufacturing facilities for supply-chain resilience", "Quick-turn commercial prototype capabilities from Eagle Electronics acquisition"], "facts_used": ["Founded 2016 via KCA Electronics and Marcel Electronics acquisitions -> /about-us", "Chicago facility added 2021 via Eagle Electronics acquisition -> /about-us", "Headquarters Schaumburg, IL -> db, / (Chicago location address)", "1,250+ employees, 7 facilities, 8 locations -> /, /about-us", "Leadership names (Shane Whiteside, etc.) -> /about-us", "Markets served list -> /", "Fabrication capabilities (layers, panel size, HDI, vias, finishes) -> /capabilities", "Assembly capabilities (turns, SMT, through-hole, BGA, fine pitch, components) -> /capabilities", "Quality certifications (AS9100D, NADCAP, ITAR, ISO9001, RoHS, IPC Class II/III) -> db, /capabilities", "Quick-turn prototype emphasis -> /, /about-us, /capabilities", "One of largest PCB manufacturers in North America claim -> /", "Field application engineers across North America -> /", "Redundant facilities -> /", "Mission statement -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Summit Interconnect is one of the largest PCB manufacturers in North America.", "founded_year": "2016", "employee_count": "1250+", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='summit-interconnect-chicago' AND approved AND profile IS NULL;
UPDATE companies SET description='Summit Medical, an Innovia Medical Company, operates from Eagan, Minnesota. The business is part of Innovia Medical, a family of specialty surgical companies that partner with medical professionals to elevate patient care and improve clinical outcomes. No founding year or founders are disclosed.

The company develops and manufactures a range of surgical and therapy products, including otology ventilation tubes, rhinology nasal splints, ophthalmology instruments, cervical biopsy punches, sterilization trays, and personal protection equipment such as face shields. Its manufacturing capabilities encompass clean-room silicone molding, plastic injection molding, bench assembly, and clean-room packaging, supported by product development, custom design, and private-label services.

