UPDATE companies SET description='Superior Moulding of Nevada was founded in 1998 in Las Vegas, Nevada, as a family-owned business. The company operates a showroom and distribution facility in Las Vegas, stocking hundreds of moulding patterns—including crown, base, door casing, chair rail, panel mouldings, corbels, columns, appliques, and ceiling medallions—in both stain-grade hardwoods (poplar, red oak, cherry, mahogany, white oak, birch, alder, maple) and paint-grade MDF. It also supplies interior and exterior doors, barn and pocket door systems, and related hardware. Local delivery is available throughout the Las Vegas Valley. The business emphasizes a large in-stock inventory for immediate pickup, personalized one-on-one assistance, and partnerships with brands such as Metrie, Fypon, Orac Decor, and Emtek to offer a broad selection.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Moulding distribution", "Door supply (interior, exterior, barn, pocket)", "Showroom product selection", "Local delivery", "Custom order sourcing", "Material consultation"], "industries": ["Residential construction", "Home remodeling", "Interior design", "Millwork"], "materials": ["Poplar", "Red Oak", "Cherry", "Mahogany", "White Oak", "Birch", "Alder", "Maple", "MDF (paint grade)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Largest moulding inventory in the Las Vegas Valley", "Hundreds of patterns stocked for immediate pickup", "Family-owned with personalized 1-on-1 customer support", "Local delivery across the Las Vegas Valley"], "facts_used": ["Founded in 1998 -> db, /about-us", "Family-owned -> db, /about-us", "Headquarters in Las Vegas, Nevada -> db, /", "Largest moulding inventory in Las Vegas Valley -> /", "Hundreds of moulding patterns stocked in Las Vegas facility -> /about-us", "Local delivery in Las Vegas Valley -> /, /about-us", "Partnerships with brands: Focal Point, Orac Decor, Metrie Wood Products, Fypon, Jeffrey Alexande